import {missions,labels,traceProgram,quizSets} from './engine.js?v=learning-flow-2';
import {normalizeWorkspace,restoreMission,rubricCriteria,rubricTotal} from './workspace.js?v=learning-flow-2';

const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',lab:'M9 3h6m-5 0v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M8 14h8',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',teacher:'m2 8 10-5 10 5-10 5ZM6 10v7c4 3 8 3 12 0v-7m4-2v8',book:'M12 5C8 2 4 3 2 4v15c3-1 6-1 10 1 4-2 7-2 10-1V4c-3-1-6-2-10 1Zm0 0v15',play:'m8 4 12 8-12 8Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',bolt:'m13 2-8 12h6l-1 8 9-12h-7Z',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',repeat:'M20 7H6l3-3M4 17h14l-3 3M20 7v5M4 17v-5',branch:'M6 3v12a4 4 0 0 0 4 4h8m-4-4 4 4-4 4M6 9h8a4 4 0 0 0 4-4V3',bug:'M8 9V7a4 4 0 0 1 8 0v2M7 9h10v7a5 5 0 0 1-10 0ZM3 10h4m10 0h4M3 15h4m10 0h4M5 21l3-3m8 0 3 3',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0m-5 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0m-5-2v4m-2-2h4',close:'m6 6 12 12M6 18 18 6',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',step:'m5 5 10 7-10 7Zm14 0v14',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',menu:'M4 6h16M4 12h16M4 18h16',info:'M12 11v6m0-10v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',up:'m6 14 6-6 6 6',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',south:'m6 10 6 6 6-6',flag:'M5 21V3c4-3 8 3 14 0v11c-6 3-10-3-14 0',copy:'M8 8h13v13H8zM16 8V3H3v13h5',stop:'M5 5h14v14H5z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.code}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=document.querySelector('main');
const navItems=[['home','home','Басты бет'],['tasks','grid','Тапсырмалар'],['lab','lab','Зертхана'],['mentor','spark','AI көмекші'],['progress','chart','Жұмыс нәтижесі']];
document.querySelector('#nav').innerHTML=navItems.map(([id,i,label])=>`<a href="#${id}" data-nav="${id}">${icon(i)}<span>${label}</span>${id==='tasks'?'<span class="nav-count">6</span>':''}</a>`).join('');
document.querySelector('#teacher-link').innerHTML=icon('teacher')+'Мұғалімге';
document.querySelector('#menu-button').innerHTML=icon('menu');
const STORAGE='ai-lab-kz-v1';
let storageOK=true;
function readState(){try{return normalizeWorkspace(JSON.parse(localStorage.getItem(STORAGE)||'{}'));}catch{return normalizeWorkspace();}}
let state=readState();
let presenting=false,demoToken=0,lastDraftKey='';
let selected=-1,program=[],position=[...missions[0].start],cursor=0,runToken=0,running=false,result=null,hintIndex=0,filter='Барлығы',message='',messageKind='info',prediction='',predictionSkipped=false,forecast=null,reflection='',aiReflection='',beforeClear=null,route='home',rubricMission=0;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageOK=false;}}
function announce(text){document.querySelector('#announcement').textContent=text;}
function completedCount(){return missions.filter(m=>state.completed[m.id]).length;}
function resetExecution(){runToken++;running=false;cursor=0;position=[...missions[selected].start];result=null;forecast=null;}
function attemptDraft(){return {programKey:JSON.stringify(program),prediction,predictionSkipped,reflection,aiReflection,hasRun:!!result,cursor,forecast,message,messageKind};}
function currentDraftKey(){return JSON.stringify({id:missions[selected].id,program,draft:{...attemptDraft(),beforeClear}});}
function persistDraft(){if(selected<0)return;const key=currentDraftKey();if(key===lastDraftKey)return;lastDraftKey=key;const id=missions[selected].id;state.programs[id]=structuredClone(program);state.drafts[id]={...attemptDraft(),beforeClear};state.activeMission=id;save();}
function applyAttempt(attempt){({program,position,cursor,result,prediction,predictionSkipped,forecast,reflection,aiReflection,beforeClear}=attempt);message=attempt.message||'Болжам жаса, содан кейін командаларды қос.';messageKind=attempt.messageKind;}
function setMission(index){const next=Math.max(0,Math.min(missions.length-1,Number(index)||0));if(next===selected)return;const initial=selected<0;persistDraft();selected=next;runToken++;running=false;hintIndex=0;const m=missions[selected];applyAttempt(restoreMission(m,state.programs[m.id],state.drafts[m.id]));if(initial)lastDraftKey=currentDraftKey();else{lastDraftKey='';persistDraft();}}
setMission(Math.max(0,missions.findIndex(m=>m.id===state.activeMission)));
function persistProgram(){persistDraft();}
function robot(){return `<svg class="robot" viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M24 7V3" stroke="currentColor" stroke-width="3"/><circle cx="24" cy="3" r="2.5" fill="#ffbb73"/><rect x="7" y="10" width="34" height="29" rx="10" fill="currentColor"/><rect x="11" y="14" width="26" height="17" rx="6" fill="#eef2f7"/><rect x="17" y="19" width="4" height="6" rx="2" fill="#244b77"/><rect x="27" y="19" width="4" height="6" rx="2" fill="#244b77"/><path d="M19 35h10" stroke="#ffbb73" stroke-width="2.5" stroke-linecap="round"/><path d="M3 20v11m42-11v11M16 42v3m16-3v3" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></svg>`;}
function board(m,pos,{mini=false}={}){let html='';for(let y=0;y<5;y++){html+='<div class="board-row" role="row">';for(let x=0;x<5;x++){const wall=m.walls.some(w=>w[0]===x&&w[1]===y);const goal=m.goal[0]===x&&m.goal[1]===y;const bot=pos[0]===x&&pos[1]===y;const start=m.start[0]===x&&m.start[1]===y;html+=`<div class="cell ${wall?'wall':''} ${goal?'goal':''} ${bot?'occupied':''} ${start?'start':''}" role="cell" aria-label="${y+1}-қатар, ${x+1}-баған${wall?', қабырға':''}${goal?', қуат көзі':''}${bot?', робот':''}">${bot?robot():goal?icon('bolt'):wall?'<span></span>':start?'<i></i>':''}</div>`;}html+='</div>';}return `<div class="board ${mini?'mini-board':''}" role="table" aria-rowcount="5" aria-colcount="5" aria-label="Робот алаңы: 5 қатар және 5 баған">${html}</div>`;}
function pageHeading(title,desc,extra=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function home(){const next=missions.findIndex(m=>!state.completed[m.id]);return `
  <div class="welcome-line"><span>Сенің оқу кеңістігің</span><a href="#method">${icon('book')} Жоба туралы</a></div>
  <section class="home-hero hero" aria-labelledby="home-title" data-enter>
    <div class="hero-copy"><h1 id="home-title" data-enter-whole>Алгоритмдік ойлау<br><span>зертханасы</span></h1><p>Идеяңды қадамдарға бөл. Роботқа жол көрсет.<br class="desktop-br"> Әр шешімнің қалай жұмыс істейтінін түсін.</p><div class="hero-actions"><button class="button btn primary" data-open="${next<0?0:next}">${icon('play')} Жаттығуды бастау</button><button class="text-button" data-quiz="initial">Бастапқы диагностика</button></div><div class="hero-foot"><span>${icon('check')} 5–8 сыныптар</span><span>${icon('check')} 6 миссия</span><span>${icon('check')} Қазақ тілінде</span></div></div>
    <div class="hero-lab-preview" data-enter-media><div class="preview-top"><span>${icon('lab')} Алғашқы алгоритм</span><span class="preview-mission">1 / 6 миссия</span></div><div class="preview-workspace"><div class="preview-map" id="demo-board">${board(missions[0],missions[0].start,{mini:true})}</div><div class="preview-code"><strong>Қадамдар реті</strong><div class="preview-code-line" data-demo-step="0"><span>1</span>${icon('right')} Оңға жүр</div><div class="preview-code-line" data-demo-step="1"><span>2</span>${icon('right')} Оңға жүр</div><div class="preview-code-line" data-demo-step="2"><span>3</span>${icon('right')} Оңға жүр</div><div class="preview-code-line" data-demo-step="3"><span>4</span>${icon('right')} Оңға жүр</div><span class="preview-finish">${icon('flag')} Мақсат</span></div></div><div class="preview-bottom"><span id="demo-status">${icon('bolt')} 0 / 4 қадам</span><button class="preview-try btn" id="demo-run" aria-controls="demo-board">${icon('play')} Орындау</button></div></div>
  </section>
  <div class="home-columns"><section class="learning-path"><div class="section-heading"><h2>Сенің оқу бағытың</h2><a href="#tasks">Барлық тапсырмалар ${icon('chevron')}</a></div><p class="section-sub">Қарапайым қадамнан ақылды алгоритмге дейін.</p><div class="path-list">${[['code','Тізбектілік','Қадамдардың дұрыс ретін тап','mint',0],['branch','Тармақталу','Шартқа қарай шешім қабылда','peach',3],['repeat','Циклдер','Қайталанатын әрекетті қысқарт','blue',2]].map(([i,title,desc,c,id])=>`<a href="#lab" class="path-row card" data-open="${id}"><span class="path-icon ${c}">${icon(i)}</span><span class="path-text"><strong>${title}</strong><span>${desc}</span></span><span class="path-meta">${id===0?'5-сынып':id===3?'7-сынып':'6-сынып'}</span>${icon(state.completed[missions[id].id]?'check':'chevron')}</a>`).join('')}</div><div class="path-progress"><span>Оқу жолың</span><div class="progress-track"><i style="width:${completedCount()/6*100}%"></i></div><strong>${completedCount()} / 6</strong></div></section>
  <aside class="home-ai"><span class="ai-symbol">${icon('spark')}</span><h2>Жауапқа өзің жет.<br>AI бағыт береді.</h2><p>Қиындыққа тірелдің бе? Дайын жауаптың орнына дұрыс сұрақтан баста.</p><a href="#mentor" class="button btn secondary">AI көмекшіні ашу ${icon('spark')}</a><div class="ai-bottom"><span class="mini-line"></span><span>Ойлануға арналған серіктес</span></div></aside></div>
  <section class="bottom-strip"><span class="bottom-icon">${icon('target')}</span><div><h2>Өзгерісіңді өзің байқа</h2><p>Алдымен бастапқы, жаттығудан кейін қорытынды диагностикадан өт.</p></div><button class="text-button" data-quiz="${state.diagnostics.initial?'final':'initial'}">${state.diagnostics.initial?'Қорытындыдан өту':'Диагностикадан өту'} ${icon('chevron')}</button></section>`;}
function tasks(){const concepts=['Барлығы',...new Set(missions.map(m=>m.concept))];const shown=missions.map((m,i)=>({...m,i})).filter(m=>filter==='Барлығы'||m.concept===filter);return pageHeading('Тапсырмалар','Әр миссияда бір дағдыңды дамыт. Қалаған тапсырмаңнан бастай аласың.',`<span class="outline-tag">${completedCount()} / 6 орындалды</span>`)+`<div class="filters" role="group" aria-label="Тақырып бойынша сүзу">${concepts.map(c=>`<button data-filter="${c}" class="filter ${filter===c?'selected':''}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div><div class="mission-list">${shown.map(m=>`<article class="mission-row"><div class="mission-number ${state.completed[m.id]?'done':''}">${state.completed[m.id]?icon('check'):String(m.i+1).padStart(2,'0')}</div><div class="mission-content"><div class="mission-tags"><span>${m.concept}</span><span>${m.grade}</span></div><h2>${m.title}</h2><p>${m.description}</p><div class="mission-details"><span>${icon('clock')} ${m.minutes} минут</span><span>${m.level}</span></div></div><button class="button btn ${state.completed[m.id]?'secondary':'primary'}" data-open="${m.i}">${state.completed[m.id]?'Қайта орындау':'Миссияны бастау'}</button></article>`).join('')}</div>`;}
function commandText(c){if(c.type==='repeat')return `${c.count} рет қайтала: ${labels[c.dir].toLowerCase()}`;if(c.type==='if')return `Егер ${labels[c.dir].toLowerCase()} жол ашық: ${labels[c.dir].toLowerCase()}, әйтпесе ${labels[c.other].toLowerCase()}`;return labels[c.dir]+' жүр';}
function programHTML(){return program.length?program.map((c,i)=>`<div class="program-line ${c.type} ${i===result?.failedBlock?'failed':''} ${cursor&&result?.trace[cursor-1]?.block===i?'executing':''}"><span class="line-num">${i+1}</span>${icon(c.type==='repeat'?'repeat':c.type==='if'?'branch':{E:'right',N:'up',W:'left',S:'south'}[c.dir])}<span>${commandText(c)}</span><div class="line-actions"><button class="icon-btn small" data-move="${i}" data-delta="-1" aria-label="${i+1}-блокты жоғары жылжыту" ${i===0||running?'disabled':''}>${icon('up')}</button><button class="icon-btn small" data-move="${i}" data-delta="1" aria-label="${i+1}-блокты төмен жылжыту" ${i===program.length-1||running?'disabled':''}>${icon('down')}</button><button class="icon-btn small remove" data-remove="${i}" aria-label="${i+1}-блокты өшіру" ${running?'disabled':''}>${icon('close')}</button></div></div>`).join(''):`<div class="program-empty">${icon('code')}<strong>Алгоритмің осы жерден басталады</strong><span>Төмендегі бағыт батырмаларын басып, бірінші команданы қос.</span></div>`;}
function directionOptions(value='E'){return Object.entries(labels).map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l.toLowerCase()}</option>`).join('');}
function comparisonHTML(){
 if(!result||cursor<result.trace.length)return '';
 const expected=forecast?.value;
 const reached=position.every((n,i)=>n===missions[selected].goal[i]);
 const actualLabel=reached?'Мақсатқа дейін':'Орындалғаны';
 const note=!reached?'Бұл әлі толық жол емес. Қатені түзетіп, болжамыңды қайта тексер.':expected==null?'Енді жолды білесің. Келесі сынаққа болжам жасап көр.':expected===cursor?'Болжамың дәл келді. Неліктен осынша қадам қажет болды?':`Болжам мен нәтиже ${Math.abs(expected-cursor)} қадамға ерекшеленді. Қай қадамды басқаша санадың?`;
 return `<div class="comparison-values"><span>Болжамың<strong>${expected==null?'Әзірге білмеймін':expected+' қадам'}</strong></span><span>${actualLabel}<strong>${cursor} қадам</strong></span></div><p>${note}</p>`;
}
function undoHTML(){return beforeClear?`<span>Алгоритм тазаланды.</span><button class="text-button" id="undo-clear">${icon('reset')} Қайтару</button>`:'';}
function lab(){const m=missions[selected];const locked=!!result;return pageHeading('Алгоритм зертханасы','Болжа. Құрастыр және тексер. Шешіміңді түсіндір.',`<a class="text-button" href="#tasks">Тапсырмалар</a>`)+`
 <div class="lab-selector"><label for="mission-select">Миссия</label><select id="mission-select">${missions.map((v,i)=>`<option value="${i}" ${selected===i?'selected':''}>${i+1}. ${v.title}</option>`).join('')}</select><span class="concept-tag">${m.concept}</span><span class="mission-time">${icon('clock')} ${m.minutes} минут</span></div>
 <p class="mission-instruction">${m.description}</p>
 <section class="prediction-step" aria-labelledby="prediction-title"><div><h2 id="prediction-title"><span class="learning-step">1</span> Алдымен болжа</h2><p>Неше қозғалыс қажет? Блоктарды емес, роботтың торлар арасындағы қадамдарын сана.</p></div><div class="prediction-fields"><label for="prediction">Қадам саны<input id="prediction" type="number" min="1" max="192" inputmode="numeric" placeholder="Мысалы, 6" value="${esc(prediction)}" ${locked||predictionSkipped?'disabled':''} aria-describedby="prediction-note"></label><label class="unsure-choice"><input id="prediction-unsure" type="checkbox" ${predictionSkipped?'checked':''} ${locked?'disabled':''}> Әзірге білмеймін</label><p id="prediction-note">${locked?'Болжам бекітілді. Өзгерту үшін роботты бастапқы орынға қайтар.':'Өз болжамыңды жаз немесе «Әзірге білмеймін» таңда.'}</p></div></section>
 <div class="lab-grid"><section class="arena-panel" aria-labelledby="arena-title"><div class="panel-title"><h3 id="arena-title">Робот алаңы</h3><span id="step-count">${cursor} қадам</span></div><div id="board-wrap">${board(m,position)}</div><div class="board-legend"><span><i class="legend-start"></i> Бастау</span><span>${icon('bolt')} Қуат көзі</span><span><i class="legend-wall"></i> Қабырға</span></div>
 <div class="run-controls" aria-label="Алгоритмді орындау"><button class="button btn primary" id="run">${icon('play')} Орындау</button><button class="button btn secondary" id="step">${icon('step')} Бір қадам</button><button class="icon-btn" id="reset-run" aria-label="Роботты бастапқы орнына қайтару" title="Роботты бастапқы орнына қайтару">${icon('reset')}</button><button class="icon-btn" id="stop-run" aria-label="Орындауды тоқтату" hidden>${icon('stop')}</button></div>
 <div id="run-status" class="run-status ${messageKind}" role="status">${icon(messageKind==='success'?'check':'info')}<span>${esc(message)}</span></div><div id="prediction-comparison" class="prediction-comparison" aria-live="polite" ${result&&cursor===result.trace.length?'':'hidden'}>${comparisonHTML()}</div>
 </section>
 <section class="editor-panel" aria-labelledby="editor-title"><div class="panel-title"><h3 id="editor-title"><span class="learning-step">2</span> Құрастыр және тексер</h3><button class="clear-button" id="clear-program" ${!program.length?'disabled':''}>${icon('trash')} Тазалау</button></div><div id="editor-undo" class="editor-undo" role="status" ${beforeClear?'':'hidden'}>${undoHTML()}</div><div class="editor-meta"><span>Менің алгоритмім</span><span id="block-count">${program.length} / 24 блок</span></div><div class="program" id="program">${programHTML()}</div><div class="command-palette"><span class="palette-label">Команда қосу</span><div class="direction-buttons">${Object.entries(labels).map(([d,l])=>`<button data-dir="${d}" class="direction-btn">${icon({E:'right',N:'up',W:'left',S:'south'}[d])}${l}</button>`).join('')}</div><details ${m.require==='repeat'?'open':''}><summary>${icon('repeat')} Қайталау блогы ${icon('down')}</summary><div class="compound-form"><label>Бағыт<select id="repeat-dir">${directionOptions()}</select></label><label>Рет саны<input type="number" id="repeat-count" min="1" max="8" value="4"></label><button class="button btn secondary" id="add-repeat">Қосу</button></div></details><details ${m.require==='if'?'open':''}><summary>${icon('branch')} Егер жол ашық болса ${icon('down')}</summary><div class="compound-form"><label>Жол ашық болса<select id="if-dir">${directionOptions()}</select></label><label>Әйтпесе<select id="else-dir">${directionOptions('N')}</select></label><button class="button btn secondary" id="add-if">Қосу</button></div></details></div>
 <details class="lab-help"><summary>${icon('spark')} Ойлануға түрткі</summary><p id="hint-text">${m.question}</p><button class="text-button" id="hint-button">Басқа кеңес алу</button><a class="text-button" href="#mentor">AI көмекшіге өту ${icon('chevron')}</a></details></section></div>
 <section id="reflection-section" class="reflection-section" ${result?.success&&cursor===result.trace.length?'':'hidden'}><span class="success-badge">${icon('check')}</span><div><h2><span class="learning-step">3</span> Шешіміңді түсіндір</h2><p>Болжамың нәтижемен сәйкес келді ме? Қай қадамды өзгерттің және неге? Одан да тиімді жол бар ма?</p><label for="reflection">Менің түсіндірмем</label><textarea id="reflection" rows="3" maxlength="1500" placeholder="Мен ... қадам болжадым. Нәтижесінде ... Себебі ...">${esc(reflection)}</textarea><label for="ai-reflection">AI көмегінен кейін не өзгерттің? <span class="optional-label">Қолдансаң ғана толтыр</span></label><textarea id="ai-reflection" rows="2" maxlength="1000" placeholder="AI маған ... деген сұрақ қойды. Мен ... өзгерттім.">${esc(aiReflection)}</textarea><div class="reflection-actions"><button id="save-reflection" class="button btn primary">Нәтижені сақтау</button><a class="text-button" href="#mentor">Шешімімді AI-мен талқылау ${icon('external')}</a></div><p id="reflection-status" role="status"></p></div></section>`;}
function getAIPrompt(){const m=missions[selected];const finished=result&&cursor===result.trace.length;const outcome=!result?'Әлі орындалмады':!finished?`${cursor} қадам орындалды, робот ${position}; орындау кідіртілген, соңғы нәтиже әлі тексерілмеді`:result.success?'мақсатқа жетті':result.error==='blocked'?`қабырғаға не шекараға тірелді, блок ${result.failedBlock+1}`:result.error==='requirement'?'мақсатқа жетті, бірақ міндетті блок әлі қолданылмады':'әлі мақсатқа жетпеді';return `Сен 5–8 сынып оқушысына алгоритмдік ойлауды дамытатын қазақтілді информатика тәлімгерісің. Дайын шешімді немесе толық командаларды бірден берме. Бір уақытта бір қысқа жетекші сұрақ қой. Оқушының болжамы мен дәлелін сұра.
Миссия: ${m.title}. ${m.description}
Алаң: 5×5; координаталар x,y 0-ден 4-ке дейін, y төмен қарай өседі. Бастау: ${m.start}; мақсат: ${m.goal}; қабырғалар: ${JSON.stringify(m.walls)}.
Алгоритм: ${program.length?program.map((c,i)=>`${i+1}. ${commandText(c)}`).join('; '):'Әлі құрылмады'}.
Қадам болжамы: ${predictionSkipped?'Әзірге білмеймін':prediction||'Әлі айтылмады'}.
Соңғы тексеру: ${outcome}.
Оқушының түсіндірмесі: ${reflection||'Әлі берілмеді'}.
Алдымен оқушыны өз шешімін ұсынуға жетеле. AI жауабын тәжірибеде тексеру керегін еске сал.`;}
function mentor(){return pageHeading('AI көмекші','Шешімді өзің тап. Жасанды интеллект ойыңды нақтылауға көмектессін.')+`<div class="mentor-layout"><section class="mentor-main"><div class="mentor-intro">${icon('spark')}<h2>Дұрыс сұрақтан бастайық</h2><p>Көмекшімен жұмыстың мақсаты — алгоритмді өз сөзіңмен түсіндіру және шешіміңді тексеру.</p></div><label for="mentor-mission">Талқылайтын миссия</label><select id="mentor-mission">${missions.map((m,i)=>`<option value="${i}" ${selected===i?'selected':''}>${m.title}</option>`).join('')}</select><div class="mentor-conversation"><div class="mentor-avatar">${icon('spark')}</div><div><strong>Жетекші сұрақ</strong><p id="mentor-hint">${missions[selected].question}</p><span class="local-label">Алдын ала дайындалған кеңес</span></div></div><div class="mentor-options"><button class="button btn secondary" id="mentor-next">Басқа кеңес алу</button><a class="text-button" href="#lab">Алгоритмімді жалғастыру ${icon('chevron')}</a></div><div class="chatgpt-handoff"><h3>Нақты AI-мен талдау</h3><p>ChatGPT жаңа бетте ашылады. Миссия мен алгоритмің сұранымға енгізілген. Кеңесті тексеріп, шешімді өзің қабылда.</p><a id="chatgpt-link" href="https://chatgpt.com/?q=${encodeURIComponent(getAIPrompt())}" target="_blank" rel="noopener" class="button btn primary">ChatGPT-де талдау ${icon('external')}</a><button class="text-button" id="copy-prompt">${icon('copy')} Сұранымды көшіру</button><p id="copy-status" role="status"></p><details><summary>ChatGPT-ге берілетін сұраным</summary><pre id="prompt-preview">${esc(getAIPrompt())}</pre></details></div></section><aside class="mentor-rules"><h2>AI-мен жұмыс ережесі</h2><ol><li><strong>Алдымен өзің ойлан</strong><p>Өз нұсқаң мен болжамыңды ұсын.</p></li><li><strong>Жауапты сұратпа</strong><p>«Келесі қадамды қалай таңдаймын?» деп сұра.</p></li><li><strong>Кеңесті сынап көр</strong><p>Роботты қадамдап жүргіз. AI де қателесуі мүмкін.</p></li><li><strong>Шешіміңді түсіндір</strong><p>Неліктен осы алгоритмді таңдадың?</p></li></ol><div class="privacy-note">${icon('info')} Жеке деректерді жазба. Қажет болса, ChatGPT-мен жұмысты мұғалім көрсетеді.</div></aside></div>`;}
function diagnosticCard(type,title){const d=state.diagnostics[type];const set=quizSets[type];return `<div class="diagnostic-record"><span>${icon(type==='initial'?'flag':'target')}</span><div><h3>${title}</h3><p class="diagnostic-phase">${set.label}</p>${d?`<strong class="diagnostic-score">${Number(d.score)||0}<small> / 5</small></strong><p>${esc(new Date(d.at).toLocaleDateString('kk-KZ',{timeZone:'Asia/Almaty'}))} · ${esc(d.variant||'A-v1')} · соңғы нәтиже</p>`:`<p>Әзірге тапсырылмады</p>`}</div><button class="button btn secondary" data-quiz="${type}">${d?'Қайта өту':'Диагностикадан өту'}</button></div>`;}
function progress(){const done=completedCount();const initial=state.diagnostics.initial,final=state.diagnostics.final;return pageHeading('Жұмыс нәтижесі','Миссиялар, түсіндірмелер және диагностика осы браузерде сақталады.',`<button class="button btn secondary" data-export>${icon('download')} Есепті жүктеу</button>`)+`
 <div class="workspace-note"><div>${icon('info')} <strong>Осы браузердегі жұмыс</strong><p>Бірнеше оқушы ортақ құрылғыны қолданса, әрқайсысына жеке браузер профилін ашыңдар. Жұмыс белгісі аккаунт құрмайды.</p></div><label for="work-label">Есепке арналған жұмыс белгісі <span>Мысалы, 5А-07. Аты-жөніңді жазудың қажеті жоқ.</span><input id="work-label" maxlength="60" value="${esc(state.workLabel)}" placeholder="5А-07"></label></div>
 ${!storageOK?'<p class="notice">Браузер сақтауға рұқсат бермеді. Есепті жүктеп ал.</p>':''}<section class="progress-summary"><div><h2>Алгоритмге апарар жолың</h2><p>${done?`${done} миссияның шешімін орындап, түсіндірмеңді сақтадың.`:'Алғашқы миссияңды орындап, шешіміңді сақтаудан баста.'}</p><div class="big-track"><i style="width:${done/6*100}%"></i></div><span>${done} / 6 миссия</span></div><span class="progress-total">${done}<small>/ 6</small></span></section>
 <div class="section-heading"><h2>Диагностика нәтижелері</h2></div><p class="section-sub">Алдымен A нұсқасын, жаттығудан кейін B нұсқасын орында. Сұрақтары бөлек, тексеретін дағдылары ортақ.</p><div class="diagnostic-grid">${diagnosticCard('initial','Бастапқы диагностика')}${diagnosticCard('final','Қорытынды диагностика')}</div>
 ${initial&&final?`<p class="comparison-note">Соңғы балдар айырмасы: <strong>${final.score-initial.score>0?'+':''}${final.score-initial.score}</strong>. ${final.variant==='B-v1'?'Бұл әртүрлі тапсырмалардағы жеке нәтиже. Оны шешімдеріңмен және мұғалім бағасымен бірге қара.':'Қорытынды нәтиже бұрынғы A нұсқасымен алынған. Жаттығудан кейін жаңа B нұсқасын өтуге болады.'}</p>`:''}
 ${state.diagnosticHistory.length?`<details class="diagnostic-history"><summary>Барлық тапсырулар · ${state.diagnosticHistory.length}</summary><ol>${state.diagnosticHistory.map(d=>`<li><span>${d.type==='initial'?'Бастапқы':'Қорытынды'} · ${esc(d.variant||'A-v1')}</span><strong>${Number(d.score)||0} / 5</strong><time>${esc(new Date(d.at).toLocaleString('kk-KZ',{timeZone:'Asia/Almaty'}))}</time></li>`).reverse().join('')}</ol></details>`:''}
 <div class="section-heading space-top"><h2>Миссиялар тарихы</h2></div><div class="history-list">${missions.map((m,i)=>{const d=state.completed[m.id],draft=state.drafts[m.id],assessment=state.assessments[m.id],total=rubricTotal(assessment?.scores);return `<article class="history-row"><span class="history-status ${d?'done':''}">${icon(d?'check':'code')}</span><div><h3>${m.title}</h3><p>${d?`${Number(d.steps)||0} қадам · ${Number(d.blocks)||0} блок · ${Number(state.attempts[m.id])||0} тексеру`:draft?.programKey&&draft.programKey!=='[]'?'Жоба сақталған · жалғастыра аласың':'Әлі орындалмады'}</p>${d?`<details><summary>Түсіндірме және болжам</summary><p>Болжам: ${d.prediction==null?'Әзірге білмеймін':esc(d.prediction)+' қадам'} · Нақтысы: ${Number(d.steps)||0} қадам</p><p>${esc(d.reflection)}</p>${d.aiReflection?`<p><strong>AI-ден кейінгі өзгеріс:</strong> ${esc(d.aiReflection)}</p>`:''}</details>`:''}${total!==null?`<p>Мұғалім рубрикасы: ${total} / 8</p>`:''}</div><button class="text-button" data-open="${i}">${d||draft?'Жалғастыру':'Бастау'} ${icon('chevron')}</button></article>`;}).join('')}</div><p class="storage-note">Деректер басқа құрылғыға автоматты түрде көшірілмейді. Есепті жүктеп сақтай аласың.</p>`;}
function rubricHTML(){const m=missions[rubricMission],assessment=state.assessments[m.id]||{},scores=assessment.scores||[],total=rubricTotal(scores);return `<section class="rubric-section" aria-labelledby="rubric-heading"><div class="section-heading"><h2 id="rubric-heading">Ойлау барысын бағалау</h2><button class="button btn secondary" id="observation-template">${icon('download')} Бақылау парағы</button></div><p>Бұл — осы браузердегі жұмысты мұғалімнің бағалауы. Әр өлшем: 0 — әлі көрсетпеді, 1 — көмекпен орындады, 2 — өздігінен орындап, түсіндірді. Бағаланбаған өлшем нөл деп есептелмейді.</p><label class="rubric-mission-label" for="rubric-mission">Бағаланатын миссия<select id="rubric-mission">${missions.map((v,i)=>`<option value="${i}" ${i===rubricMission?'selected':''}>${v.title}</option>`).join('')}</select></label><div class="rubric-list">${rubricCriteria.map((criterion,i)=>`<div class="rubric-row"><div><h3>${criterion.title}</h3><p>${criterion.evidence}</p></div><label for="rubric-score-${i}" class="sr-only">${criterion.title}</label><select id="rubric-score-${i}" data-rubric="${i}"><option value="">Бағаланбады</option>${[0,1,2].map(score=>`<option value="${score}" ${scores[i]===score?'selected':''}>${score} · ${['Әлі көрсетпеді','Көмекпен','Өздігінен'][score]}</option>`).join('')}</select></div>`).join('')}</div><label for="rubric-note">Бақылаудан нақты мысал<textarea id="rubric-note" rows="2" maxlength="1000" placeholder="Оқушының қандай әрекеті не түсіндірмесі бағаға негіз болды?">${esc(assessment.note||'')}</textarea></label><div class="rubric-bottom"><strong id="rubric-total">${total===null?'Бағалау аяқталмады':total+' / 8 балл'}</strong><span id="rubric-save-status" role="status">${assessment.at?'Осы браузерде сақталған':'Өлшемдерді бағалағанда автоматты сақталады.'}</span><button class="text-button" data-export>Толық есепті жүктеу ${icon('download')}</button></div></section>`;}
function saveRubric(){const id=missions[rubricMission].id;const scores=rubricCriteria.map((_,i)=>{const v=document.querySelector('#rubric-score-'+i).value;return v===''?null:Number(v);});state.assessments[id]={scores,note:document.querySelector('#rubric-note').value,at:new Date().toISOString()};save();const total=rubricTotal(scores);document.querySelector('#rubric-total').textContent=total===null?'Бағалау аяқталмады':total+' / 8 балл';document.querySelector('#rubric-save-status').textContent=storageOK?'Осы браузерде сақталды.':'Сақтау қолжетімсіз. Толық есепті жүктеңіз.';}
function teacher(){rubricMission=selected;return pageHeading('Мұғалім кеңістігі','TamashaLike-ты сабақта қолдану және оқушының ойлау барысын бақылау.',`<a href="#method" class="button btn secondary">${icon('book')} Педагогикалық идея</a>`)+`<section class="teacher-banner"><div><h2>Бір сабақ. Бір мәселе.<br>Оқушының өз шешімі.</h2><p>5–8 сыныптарға арналған 45 минуттық сабақ үлгісі. Сынып деңгейіне қарай бір миссияны таңдаңыз.</p><button class="button btn primary" id="present-mode">${icon('play')} Экранда көрсету</button></div><div class="lesson-duration"><strong>45</strong><span>минут</span></div></section><div class="teacher-columns"><section><div class="section-heading"><h2>Сабақтың жүру реті</h2></div><ol class="lesson-timeline">${[['5 мин','Бастапқы диагностика','A нұсқасымен бастапқы түсінігін анықтаңыз. Нәтижені «Жұмыс нәтижесі» бөлімінен қараңыз.'],['5 мин','Мәселені талдау','Мақсат пен кедергіні анықтатыңыз. Код құрғызбай тұрып, шешімді ауызша айтқызыңыз.'],['15 мин','Алгоритмді құру және сынау','Бір миссияны таңдаңыз. Оқушылар болжап, алгоритм құрады және қадамдап тексереді.'],['10 мин','AI-мен талқылау','Дайын жауап емес, жетекші сұрақ сұратуды көрсетіңіз. AI кеңесін робот алаңында тексертіңіз.'],['10 мин','Түсіндіру және бағалау','Шешімін жаздырыңыз, B нұсқасын өткізіңіз. Төмендегі рубрикамен нақты әрекеттерін бағалаңыз.']].map(([time,title,desc])=>`<li><span>${time}</span><div><h3>${title}</h3><p>${desc}</p></div></li>`).join('')}</ol></section><aside class="assessment-panel"><h2>Бақылау дескрипторлары</h2><p>Әр тармақты оқушы әрекеті мен түсіндірмесі арқылы бағалаңыз.</p><ul>${['Мақсат пен кедергіні анықтайды','Командаларды дұрыс реттейді','Болжамын орындау нәтижесімен салыстырады','Қате қадамды табады және түзетеді','Цикл не шарттың қызметін түсіндіреді','Өз шешімін дәлелдейді'].map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul><div class="teacher-local"><h3>Осы құрылғыдағы жұмыс</h3><p>${completedCount()} / 6 миссия сақталған. Бұл бөлім бүкіл сыныптың деректерін жинамайды.</p><button class="button btn secondary" data-export>${icon('download')} Жергілікті есепті жүктеу</button></div></aside></div>${rubricHTML()}<section class="teacher-note">${icon('info')}<p>Мектептің AI қолдану тәртібін ескеріңіз. Сыртқы ChatGPT қолжетімсіз болса, тапсырмалар мен дайын кеңестерді платформа ішінде орындауға болады.</p></section>`;}
function method(){return pageHeading('Педагогикалық идея','«TamashaLike: жасанды интеллект арқылы оқушылардың алгоритмдік ойлау қабілетін дамыту»')+`<article class="method-article"><section class="method-lead"><span class="method-mark">${icon('lab')}</span><div><h2>Оқушы — шешім авторы.<br>Жасанды интеллект — ойлау серіктесі.</h2><p>Идеяның өзегі — AI-ді дайын код беретін құрал ретінде емес, оқушыны өз алгоритмін түсіндіруге жетелейтін сұхбаттас ретінде қолдану.</p></div></section><section><h2>Мақсат</h2><p>5–8 сынып оқушыларының мәселені бөліктерге жіктеу, әрекеттерді реттеу, шарт пен циклді қолдану, қателерді анықтау және шешімін негіздеу дағдыларын дамыту.</p></section><section><h2>Қалай жұмыс істейді?</h2><div class="method-steps">${[['Мәселені түсіну','Мақсатты, бастапқы шартты және кедергіні атайды.'],['Болжам жасау','Қанша қадам қажет екенін алдын ала болжайды.'],['Алгоритмді құру','Қозғалыс, цикл және шарт блоктарын біріктіреді.'],['Тексеру және талқылау','Орындау нәтижесін көреді, AI-ге жетекші сұрақ қояды.'],['Дәлелдеу','Шешімін жазады, балама жолды салыстырады.']].map(([t,d],i)=>`<div><span>${i+1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section><h2>AI-дің нақты рөлі</h2><p>Платформа ChatGPT-ге тапсырма, алаң координаталары, оқушы алгоритмі және соңғы тексеру нәтижесі бар сұраным дайындайды. ChatGPT жаңа бетте ашылады. Нұсқаулық дайын жауапты бермей, бір уақытта бір жетекші сұрақ қоюды сұрайды.</p><p>Платформа ішіндегі кеңестер алдын ала жазылған. Олар тілдік модель жауабы ретінде көрсетілмейді.</p></section><section><h2>Нәтижені қалай бағалаймыз?</h2><p>Бастапқы A және қорытынды B нұсқаларында бірдей дағдыларға бағытталған бес түрлі сұрақ бар. Әр тапсырудың нұсқасы, балы және уақыты сақталады. Балдар айырмасын жеке бақылау үшін қолданыңыз; әдістің тиімділігін дәлелдеу үшін бірнеше сабақтағы нақты жұмыстар мен бақылаулар қажет.</p><p>Есепке қадамдар, блоктар, тексеру саны, болжам, түсіндірме, AI-ден кейінгі өзгеріс және мұғалімнің 0–8 балдық рубрикасы енгізіледі. Түсіндірменің мағынасын мұғалім бағалайды. Автоматты белгі оқушының ойлау сапасына қойылған баға емес.</p></section><section><h2>Байқауға қандай дәлел дайындаймыз?</h2><ul class="evidence-list"><li><strong>Бастапқы шешім:</strong> оқушының болжамын және алғашқы алгоритмін көрсетіңіз.</li><li><strong>Көмектің әсері:</strong> AI қойған нақты сұрақты және одан кейін өзгерген қадамды салыстырыңыз.</li><li><strong>Өз түсіндірмесі:</strong> оқушы неліктен түзеткенін өз сөзімен негіздесін.</li><li><strong>Бақылау:</strong> рубриканы нақты әрекетпен толтырып, A/B нәтижелерімен бірге есепке сақтаңыз.</li></ul><p>Нақты оқушы жұмыстары әлі жиналмаса, көрсетілімді «демонстрациялық сабақ» деп таныстырыңыз. Байқауға бақылаумен расталған нақты жұмыстарды ұсыныңыз.</p><a class="text-button" href="#teacher">Рубрика мен бақылау парағын ашу ${icon('chevron')}</a></section><section><h2>Байқауда көрсету сценарийі</h2><ol class="demo-list"><li>«Кедергіні айналып өт» миссиясында мәселені бөліктерге жіктеуді көрсетіңіз.</li><li>Әдейі қате команда қосып, қадамдап орындаңыз.</li><li>ChatGPT-ге дайындалған сұранымды ашып, жетекші сұрақ тәсілін түсіндіріңіз.</li><li>Алгоритмді түзетіп, түсіндірмені сақтаңыз және есепті жүктеңіз.</li></ol><a href="#lab" class="button btn primary">${icon('lab')} Зертхананы ашу</a></section></article>`;}
function render(){
 demoToken++;
 if(running){runToken++;running=false;message='Орындау кідіртілді. «Орындау» батырмасымен жалғастыр.';messageKind='info';}
 persistDraft();
 const target=location.hash.slice(1)||'home';route=['home','tasks','lab','mentor','progress','teacher','method'].includes(target)?target:'home';
 const title=navItems.find(n=>n[0]===route)?.[2]||({teacher:'Мұғалімге',method:'Жоба туралы'}[route]);
 document.querySelector('#breadcrumb').textContent=title;document.title=`${title} · TamashaLike`;
 document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===route);if(el.dataset.nav===route)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 document.querySelector('#teacher-link').classList.toggle('active',route==='teacher');
 main.dataset.route=route;main.innerHTML=({home,tasks,lab,mentor,progress,teacher,method}[route])();
 if(route==='lab')updateRunning();
 setMenu(false);document.body.classList.toggle('presentation',presenting&&route==='lab');window.scrollTo({top:0,behavior:'instant'});
}
async function runHomeDemo(){
 const button=document.querySelector('#demo-run');if(!button||button.disabled)return;
 const token=++demoToken;
 const result=traceProgram(missions[0],Array.from({length:4},()=>({type:'move',dir:'E'})));
 button.disabled=true;button.setAttribute('aria-busy','true');
 document.querySelector('#demo-board').innerHTML=board(missions[0],missions[0].start,{mini:true});
 document.querySelectorAll('[data-demo-step]').forEach(el=>el.classList.remove('is-current'));
 document.querySelector('#demo-status').textContent='0 / 4 қадам';
 for(let i=0;i<result.trace.length;i++){
  await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?80:420));
  if(token!==demoToken)return;
  document.querySelector('#demo-board').innerHTML=board(missions[0],result.trace[i].position,{mini:true});
  document.querySelectorAll('[data-demo-step]').forEach((el,j)=>el.classList.toggle('is-current',i===j));
  document.querySelector('#demo-status').textContent=`${i+1} / 4 қадам`;
 }
 button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=icon('reset')+' Қайталау';
 document.querySelector('#demo-status').innerHTML=icon('check')+' Мақсатқа жетті';
 announce('Робот төрт қадамда мақсатқа жетті. Енді өз алгоритміңді құрастырып көр.');
}
function openMission(i){setMission(i);if(location.hash==='#lab')render();else location.hash='lab';}
function syncEditor({keepUndo=false}={}){
 if(!keepUndo)beforeClear=null;
 persistProgram();
 document.querySelector('#program').innerHTML=programHTML();
 document.querySelector('#block-count').textContent=`${program.length} / 24 блок`;
 document.querySelector('#board-wrap').innerHTML=board(missions[selected],position);
 document.querySelector('#step-count').textContent='0 қадам';
 document.querySelector('#reflection-section').hidden=true;
 document.querySelector('#prediction-comparison').hidden=true;
 const undo=document.querySelector('#editor-undo');undo.hidden=!beforeClear;undo.innerHTML=undoHTML();
 updateRunning();setStatus('Алгоритм жаңартылды. Болжамыңды тексер.','info');
}
function focusProgram(index,delta){const row=Math.max(0,Math.min(index,program.length-1));const preferred=document.querySelector(`[data-move="${row}"][data-delta="${delta}"]`);const fallback=document.querySelector(`[data-remove="${row}"]`);(preferred&&!preferred.disabled?preferred:fallback||document.querySelector('[data-dir="E"]'))?.focus();}
function addCommand(command){if(running)return;if(program.length>=24){setStatus('24 блок шегіне жеттің. Қайталанатын қадамдарды циклмен қысқарт.','error');return;}program.push(command);resetExecution();syncEditor();}
function setStatus(text,kind='info'){message=text;messageKind=kind;const el=document.querySelector('#run-status');if(el){el.className=`run-status ${kind}`;el.innerHTML=icon(kind==='success'?'check':'info')+`<span>${esc(text)}</span>`;}persistDraft();announce(text);}
function updateRunning(){
 for(const id of ['run','step','undo-clear']){const el=document.getElementById(id);if(el)el.disabled=running;}
 const clear=document.querySelector('#clear-program');if(clear)clear.disabled=running||!program.length;
 document.querySelectorAll('.command-palette button,#mission-select,.command-palette select,.command-palette input').forEach(el=>el.disabled=running);
 if(running)document.querySelectorAll('.line-actions button').forEach(el=>el.disabled=true);
 const input=document.querySelector('#prediction'),unsure=document.querySelector('#prediction-unsure');
 if(input)input.disabled=!!result||predictionSkipped;
 if(unsure)unsure.disabled=!!result;
 const note=document.querySelector('#prediction-note');if(note)note.textContent=result?'Болжам бекітілді. Өзгерту үшін роботты бастапқы орынға қайтар.':'Өз болжамыңды жаз немесе «Әзірге білмеймін» таңда.';
 const stop=document.querySelector('#stop-run');if(stop)stop.hidden=!running;
}
function updateArena(){document.querySelector('#board-wrap').innerHTML=board(missions[selected],position);document.querySelector('#step-count').textContent=`${cursor} қадам`;document.querySelector('#program').innerHTML=programHTML();}
function finishRun(){
 running=false;updateRunning();updateArena();
 if(result.success){setStatus(`Мақсатқа ${cursor} қадамда жеттің. Болжамыңмен салыстырып, шешіміңді түсіндір.`,'success');document.querySelector('#reflection-section').hidden=false;}
 else if(result.error==='blocked')setStatus(`${result.failedBlock+1}-блокта жол жабық: қабырға немесе алаң шеті. Осы команданы өзгертіп көр.`,'error');
 else if(result.error==='requirement')setStatus(`Мақсатқа жеттің. Бұл миссияда ${missions[selected].require==='repeat'?'қайталау':'шарт'} блогын қолдану қажет.`,'error');
 else setStatus('Командалар аяқталды, робот мақсатқа әлі жетпеді. Қалған жолды толықтыр.','info');
 const comparison=document.querySelector('#prediction-comparison');comparison.hidden=false;comparison.innerHTML=comparisonHTML();persistDraft();
}
function prepareRun(){if(!program.length){setStatus('Алдымен кемінде бір команда қос.','error');return false;}try{result=traceProgram(missions[selected],program);forecast={value:predictionSkipped?null:Number(prediction),unsure:predictionSkipped};return true;}catch(e){setStatus(e.message,'error');return false;}}
async function execute(stepOnly=false){
 if(running)return;
 if(!predictionSkipped&&(!prediction||!Number.isInteger(Number(prediction))||Number(prediction)<1||Number(prediction)>192)){
   setStatus('Алдымен 1–192 аралығындағы қадам болжамын жаз немесе «Әзірге білмеймін» таңда.','error');document.querySelector('#prediction').focus();return;
 }
 if(!result||cursor>=result.trace.length){resetExecution();if(!prepareRun())return;state.attempts[missions[selected].id]=(Number(state.attempts[missions[selected].id])||0)+1;}
 document.querySelector('#reflection-section').hidden=true;
 document.querySelector('#prediction-comparison').hidden=true;
 const token=++runToken;running=true;updateRunning();setStatus('Алгоритм орындалып жатыр…');
 if(matchMedia('(max-width:720px)').matches)document.querySelector('#board-wrap').scrollIntoView({block:'start',behavior:'instant'});
 if(stepOnly){if(result.trace[cursor]){position=[...result.trace[cursor].position];cursor++;}running=false;updateRunning();updateArena();if(cursor>=result.trace.length)finishRun();else setStatus(`${cursor}-қадам орындалды. Келесі команда не істейді?`);return;}
 while(cursor<result.trace.length){await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?80:390));if(token!==runToken)return;position=[...result.trace[cursor].position];cursor++;updateArena();persistDraft();}
 if(token===runToken)finishRun();
}
let quizType='initial',quizAnswers=[],quizIndex=0;
const dialog=document.querySelector('#quiz-dialog');
function quizStart(type){quizType=type==='final'?'final':'initial';quizAnswers=[];quizIndex=0;quizRender();dialog.showModal();}
function quizRender(){const set=quizSets[quizType],questions=set.questions,q=questions[quizIndex];document.querySelector('#quiz-content').innerHTML=`<div class="quiz-head"><span>${quizType==='initial'?'Бастапқы':'Қорытынды'} диагностика · ${quizType==='initial'?'A':'B'}</span><button class="icon-btn" data-close-quiz aria-label="Диагностиканы жабу">${icon('close')}</button></div><div class="quiz-progress"><i style="width:${quizIndex/questions.length*100}%"></i></div><p class="quiz-counter">${quizIndex+1} / ${questions.length} сұрақ · ${quizType==='initial'?'жаттығуға дейін':'жаттығудан кейін'}</p><h2 id="quiz-heading">${q.q}</h2><fieldset class="quiz-answers"><legend class="sr-only">Жауабыңды таңда</legend>${q.options.map((o,i)=>`<label><input type="radio" name="answer" value="${i}" ${quizAnswers[quizIndex]===i?'checked':''}><span>${o}</span></label>`).join('')}</fieldset><div class="quiz-actions"><button class="button btn secondary" id="quiz-back" ${quizIndex===0?'disabled':''}>Артқа</button><button class="button btn primary" id="quiz-next" ${quizAnswers[quizIndex]===undefined?'disabled':''}>${quizIndex===questions.length-1?'Нәтижені көру':'Келесі сұрақ'}</button></div>`;}
function quizFinish(){
 const set=quizSets[quizType],questions=set.questions;
 const score=quizAnswers.filter((answer,i)=>answer===questions[i].answer).length;
 const record={score,answers:[...quizAnswers],at:new Date().toISOString(),variant:set.variant};
 state.diagnostics[quizType]=record;state.diagnosticHistory.push({...record,type:quizType});save();
 document.querySelector('#quiz-content').innerHTML=`<div class="quiz-head"><span>Диагностика аяқталды · ${quizType==='initial'?'A':'B'}</span><button class="icon-btn" data-close-quiz aria-label="Диагностиканы жабу">${icon('close')}</button></div><span class="quiz-result">${score}<small>/ ${questions.length}</small></span><h2 id="quiz-heading">${quizType==='final'?'Енді шешімдеріңді салыстырып көр.':score>=4?'Жақсы бастама. Енді тәжірибеде сына.':'Қай дағдыларды жаттықтыру керегін білдік.'}</h2><div class="quiz-review">${questions.map((q,i)=>`<div class="${quizAnswers[i]===q.answer?'correct':'incorrect'}">${icon(quizAnswers[i]===q.answer?'check':'info')}<span><strong>${q.skill}</strong><small>${q.options[q.answer]}</small></span></div>`).join('')}</div><p class="storage-note">${storageOK?'Нәтиже мен тапсыру тарихы осы браузерде сақталды.':'Браузер сақтауға рұқсат бермеді. Жұмыс нәтижесінен есепті жүктеп ал.'}</p><button class="button btn primary" id="quiz-to-results">Жұмыс нәтижесін ашу</button>`;
}
function downloadCSV(rows,filename){
 const quote=value=>{const raw=String(value??'');const safe=/^[=+@\-\t\r]/.test(raw)?"'"+raw:raw;return '"'+safe.replaceAll('"','""')+'"';};
 const csv='\uFEFF'+rows.map(row=>row.map(quote).join(';')).join('\r\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));
 const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('CSV есебі жүктелді.');
}
function exportReport(){
 persistDraft();
 const rows=[['TamashaLike','Осы браузердегі жұмыс есебі'],['Жұмыс белгісі',state.workLabel||'көрсетілмеді'],['Есеп күні',new Date().toISOString()],['Бастапқы диагностика',state.diagnostics.initial?.score??'тапсырылмады',state.diagnostics.initial?.variant||'A-v1'],['Қорытынды диагностика',state.diagnostics.final?.score??'тапсырылмады',state.diagnostics.final?.variant||(state.diagnostics.final?'A-v1':'B-v1')],[],['САҚТАЛҒАН ШЕШІМДЕР'],['Миссия','Мәртебе','Қадам','Блок','Тексеру саны','Болжам','Түсіндірме','AI-ден кейінгі өзгеріс','Сақталған уақыт',...rubricCriteria.map(c=>c.title),'Рубрика / 8','Мұғалім бақылауы'],...missions.map(m=>{const d=state.completed[m.id],assessment=state.assessments[m.id];return [m.title,d?'сақталған':'орындалмаған',d?.steps,d?.blocks,state.attempts[m.id]||0,d?.prediction??(d?'Әзірге білмеймін':''),d?.reflection,d?.aiReflection,d?.at,...rubricCriteria.map((_,i)=>assessment?.scores?.[i]??'бағаланбады'),rubricTotal(assessment?.scores)??'аяқталмады',assessment?.note];}),[],['АҒЫМДАҒЫ ЖОБАЛАР'],['Миссия','Алгоритм','Болжам','Түсіндірме жобасы','AI туралы жазба'],...missions.filter(m=>state.drafts[m.id]).map(m=>{const d=state.drafts[m.id];return [m.title,(state.programs[m.id]||[]).map(commandText).join('; '),d.predictionSkipped?'Әзірге білмеймін':d.prediction,d.reflection,d.aiReflection];}),[],['ДИАГНОСТИКА ТАРИХЫ'],['Кезең','Нұсқа','Балл / 5','Уақыт'],...state.diagnosticHistory.map(d=>[d.type==='initial'?'Бастапқы':'Қорытынды',d.variant||'A-v1',d.score,d.at])];
 downloadCSV(rows,'TamashaLike-natizhe.csv');
}
function exportObservationTemplate(){downloadCSV([['TamashaLike','Мұғалімнің бақылау парағы · бос үлгі'],['Жұмыс белгісі','Күні','Сынып','Миссия','Бастапқы болжам','Нақты қадам','Алғашқы қате','Оқушының түсіндірмесі','AI қойған сұрақ (қолданылса)','Одан кейінгі өзгеріс',...rubricCriteria.map(c=>c.title+' / 2'),'Бастапқы A / 5','Қорытынды B / 5','Келесі оқу қадамы'],[]],'TamashaLike-baqylau-paragy.csv');}
main.addEventListener('click',async e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.id==='demo-run'){await runHomeDemo();return;}
 if(b.hasAttribute('data-open')){e.preventDefault();openMission(b.dataset.open);return;}
 if(b.hasAttribute('data-quiz')){quizStart(b.dataset.quiz);return;}
 if(b.hasAttribute('data-export')){exportReport();return;}
 if(b.hasAttribute('data-filter')){filter=b.dataset.filter;main.innerHTML=tasks();return;}
 if(b.hasAttribute('data-dir')){addCommand({type:'move',dir:b.dataset.dir});return;}
 if(b.hasAttribute('data-remove')){if(running)return;const index=Number(b.dataset.remove);program.splice(index,1);resetExecution();syncEditor();focusProgram(index);return;}
 if(b.hasAttribute('data-move')){if(running)return;const i=Number(b.dataset.move),j=i+Number(b.dataset.delta);if(j<0||j>=program.length)return;[program[i],program[j]]=[program[j],program[i]];resetExecution();syncEditor();focusProgram(j,b.dataset.delta);return;}
 switch(b.id){
 case 'add-repeat':{const count=Number(document.querySelector('#repeat-count').value);if(!Number.isInteger(count)||count<1||count>8){setStatus('Қайталау санын 1–8 аралығында жаз.','error');return;}addCommand({type:'repeat',dir:document.querySelector('#repeat-dir').value,count});break;}
 case 'add-if':addCommand({type:'if',dir:document.querySelector('#if-dir').value,other:document.querySelector('#else-dir').value});break;
 case 'clear-program':if(!running&&program.length){beforeClear={program:structuredClone(program),draft:attemptDraft()};program=[];resetExecution();syncEditor({keepUndo:true});setStatus('Алгоритм тазаланды. Қайтару батырмасымен қалпына келтіре аласың.');document.querySelector('#undo-clear').focus();}break;
 case 'undo-clear':if(beforeClear&&!running){const snapshot=beforeClear;applyAttempt(restoreMission(missions[selected],snapshot.program,snapshot.draft));beforeClear=null;persistDraft();main.innerHTML=lab();updateRunning();document.querySelector('#clear-program').focus();announce('Алгоритм мен әрекетің қалпына келтірілді.');}break;
 case 'reset-run':resetExecution();updateArena();updateRunning();document.querySelector('#reflection-section').hidden=true;document.querySelector('#prediction-comparison').hidden=true;setStatus('Робот бастапқы орынға оралды. Алгоритмің мен түсіндірмең сақталды. Болжамыңды өзгерте аласың.');break;
 case 'stop-run':runToken++;running=false;updateArena();updateRunning();setStatus('Орындау тоқтатылды. Жалғастыру үшін «Орындау» батырмасын бас.');break;
 case 'run':await execute();break;
 case 'step':await execute(true);break;
 case 'hint-button':document.querySelector('#hint-text').textContent=missions[selected].hint[hintIndex++%missions[selected].hint.length];break;
 case 'save-reflection':{
   reflection=document.querySelector('#reflection').value.trim();aiReflection=document.querySelector('#ai-reflection').value.trim();const status=document.querySelector('#reflection-status');
   if(!result?.success||cursor!==result.trace.length)return;
   if(reflection.length<15){status.textContent='Шешіміңді кемінде бір сөйлеммен түсіндір (15 таңбадан кем емес).';document.querySelector('#reflection').focus();return;}
   state.completed[missions[selected].id]={steps:cursor,blocks:program.length,prediction:forecast?.value??null,predictionSkipped:forecast?.unsure??false,reflection,aiReflection,at:new Date().toISOString()};persistDraft();
   status.innerHTML=storageOK?`Нәтижең сақталды. <a href="#progress">Жұмыс нәтижесін көру</a>`:'Браузер сақтауға рұқсат бермеді. Есепті жүктеп ал.';b.textContent='Сақталды';announce(status.textContent);break;
 }
 case 'mentor-next':document.querySelector('#mentor-hint').textContent=missions[selected].hint[hintIndex++%missions[selected].hint.length];break;
 case 'copy-prompt':try{await navigator.clipboard.writeText(getAIPrompt());document.querySelector('#copy-status').textContent='Сұраным көшірілді. ChatGPT-ге қойып, талқылауды баста.';}catch{document.querySelector('#copy-status').textContent='Автоматты көшіру қолжетімсіз. Төмендегі сұранымды ашып, мәтінді қолмен көшір.';const details=document.querySelector('.chatgpt-handoff details');details.open=true;const range=document.createRange();range.selectNodeContents(document.querySelector('#prompt-preview'));getSelection().removeAllRanges();getSelection().addRange(range);}break;
 case 'present-mode':presenting=true;openMission(selected);break;
 case 'observation-template':exportObservationTemplate();break;
 }
});
main.addEventListener('change',e=>{
 if(e.target.id==='mission-select'){setMission(e.target.value);main.innerHTML=lab();updateRunning();}
 if(e.target.id==='mentor-mission'){setMission(e.target.value);main.innerHTML=mentor();}
 if(e.target.id==='prediction-unsure'){predictionSkipped=e.target.checked;if(predictionSkipped)prediction='';const input=document.querySelector('#prediction');input.disabled=predictionSkipped;input.value=prediction;persistDraft();}
 if(e.target.id==='rubric-mission'){rubricMission=Number(e.target.value);document.querySelector('.rubric-section').outerHTML=rubricHTML();document.querySelector('#rubric-mission').focus();}
 if(e.target.hasAttribute('data-rubric'))saveRubric();
});
main.addEventListener('input',e=>{
 if(e.target.id==='prediction')prediction=e.target.value;
 if(e.target.id==='reflection')reflection=e.target.value;
 if(e.target.id==='ai-reflection')aiReflection=e.target.value;
 if(['prediction','reflection','ai-reflection'].includes(e.target.id))persistDraft();
 if(e.target.id==='work-label'){state.workLabel=e.target.value;save();}
 if(e.target.id==='rubric-note')saveRubric();
});
dialog.addEventListener('change',e=>{if(e.target.name==='answer'){quizAnswers[quizIndex]=Number(e.target.value);document.querySelector('#quiz-next').disabled=false;}});
dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close-quiz'))dialog.close();if(b.id==='quiz-back'){quizIndex--;quizRender();}if(b.id==='quiz-next'&&quizAnswers[quizIndex]!==undefined){if(quizIndex<quizSets[quizType].questions.length-1){quizIndex++;quizRender();}else quizFinish();}if(b.id==='quiz-to-results'){dialog.close();if(location.hash==='#progress')render();else location.hash='progress';}});
dialog.addEventListener('close',()=>{if(route==='progress'||route==='home')render();});
const narrow=matchMedia('(max-width:720px)');
function setMenu(open){document.body.classList.toggle('menu-open',open);document.querySelector('#menu-button').setAttribute('aria-expanded',String(open));document.querySelector('#sidebar').inert=narrow.matches&&!open;}
document.querySelector('#menu-button').addEventListener('click',()=>setMenu(!document.body.classList.contains('menu-open')));
narrow.addEventListener('change',()=>setMenu(false));
document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar,#menu-button'))setMenu(false);});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();});
document.querySelector('#exit-presentation').addEventListener('click',()=>{presenting=false;document.body.classList.remove('presentation');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){presenting=false;document.body.classList.remove('presentation');setMenu(false);}});
window.addEventListener('hashchange',()=>{if(route==='lab'&&location.hash!=='#lab')presenting=false;render();main.focus({preventScroll:true});});
render();

window.addEventListener('pagehide',persistDraft);
